function generateTemplateDataUrl({
  containerSize = 600,
  borderSize = 4,
  paddingSize = 4,
  brand,
  name,
  specifications = ''
}) {
  const rawHTML =
    /* HTML */
    `
      <style>
        @font-face {
          font-family: 'Snowburst One';
          font-style: normal;
          font-weight: 400;
          src: url(data:font/woff2;charset=utf-8;base64,)
            format('woff2');
        }

        #container {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: space-between;
          width: ${containerSize}px;
          height: ${containerSize}px;
          border: ${borderSize}px groove palevioletred;
          padding: ${paddingSize}px;
        }

        #brand {
          font-family: 'Snowburst One', system-ui;
          font-weight: 400;
          font-style: normal;
          font-size: 64px;
        }

        #name {
          white-space: break-spaces;
          font-family: 'Snowburst One', system-ui;
          font-weight: 400;
          font-style: normal;
          font-size: 32px;
        }

        #specifications {
          font-family: 'Snowburst One', system-ui;
          font-weight: 400;
          font-style: normal;
          font-size: 24px;
        }

        #top {
          display: flex;
          flex-direction: column;
          align-items: center;
        }

        #bottom {
          display: flex;
          height: 40px;
          width: 100%;
          justify-content: flex-end;
          align-items: center;
        }

        #logo {
          font-size: 24px;
          color: hotpink;
          font-family: 'Snowburst One';
        }
      </style>
      <div id="container">
        <div id="top">
          <span id="brand">${brand}</span>
          <span id="name">${name}</span>
          <span id="specifications">${specifications}</span>
        </div>
        <div id="bottom">
          <span id="logo">Pinklet</span>
        </div>
      </div>
    `

  const dataUrl = `
    data:image/svg+xml, ${encodeURIComponent(
      /* HTML */
      `<svg
        xmlns="http://www.w3.org/2000/svg"
        width="${containerSize + 2 * borderSize + 2 * paddingSize}px"
        height="${containerSize + 2 * borderSize + 2 * paddingSize}px"
      >
        <foreignObject width="100%" height="100%"
          ><div xmlns="http://www.w3.org/1999/xhtml">
            ${rawHTML.replace(/<br>/g, '<br/>').replace(/&/g, '&amp;')}
          </div></foreignObject
        >
      </svg>`
    )}   
`

  return dataUrl.trim()
}

/** @type { Product } */
const { product } = context

if (!product) throw new Error('NO_PRODUCT')

const dataUrl = generateTemplateDataUrl({
  borderSize: 8,
  containerSize: 600,
  paddingSize: 4,
  brand: product.brand_en,
  name: product.name_en,
  specifications: product.specifications_en || ''
})

await log({ msg: { thumbnailTemplateDataUrl: dataUrl } })

Object.assign(context, { thumbnailTemplateDataUrl: dataUrl })
